@Entity@Table(name="spms_rating_dimension_result",uniqueConstraints=@UniqueConstraint(name="uk_spms_rating_dimension_result",columnNames={"agency_id","item_result_id","dimension_id"}))public class PerformanceRatingDimensionResult extends RspAuditedEntity{@Column(name="assessment_id",nullable=false,length=36)private String assessmentId;@Column(name="item_result_id",nullable=false,length=36)private String itemResultId;@Column(name="dimension_id",nullable=false,length=36)private String dimensionId;@Column(name="dimension_code",nullable=false,length=80)private String dimensionCode;@Column(name="dimension_type",nullable=false,length=30)private String dimensionType;@Column(name="actual_value",precision=19,scale=6)private BigDecimal actualValue;@Column(name="manual_band_id",length=36)private String manualBandId;@Column(name="matched_level_id",nullable=false,length=36)private String matchedLevelId;@Column(name="matched_band_id",nullable=false,length=36)private String matchedBandId;@Column(name="numeric_score",nullable=false,precision=19,scale=6)private BigDecimal numericScore;@Column(name="dimension_weight",nullable=false,precision=7,scale=4)private BigDecimal dimensionWeight;@Column(name="weighted_contribution",nullable=false,precision=19,scale=8)private BigDecimal weightedContribution;@Column(length=2000)private String narrative;protected PerformanceRatingDimensionResult(){}public PerformanceRatingDimensionResult(String a,String assessment,String item,String dimension,String code,String type,BigDecimal actual,String manual,String level,String band,BigDecimal score,BigDecimal weight,BigDecimal contribution,String narrative){super(a);assessmentId=requiredText(assessment,"assessmentId");itemResultId=requiredText(item,"itemResultId");dimensionId=requiredText(dimension,"dimensionId");dimensionCode=requiredText(code,"dimensionCode");dimensionType=requiredText(type,"dimensionType");actualValue=actual;manualBandId=optionalText(manual);matchedLevelId=requiredText(level,"matchedLevelId");matchedBandId=requiredText(band,"matchedBandId");numericScore=score;dimensionWeight=weight;weightedContribution=contribution;this.narrative=optionalText(narrative);}public String getAssessmentId(){return assessmentId;}public String getItemResultId(){return itemResultId;}public String getDimensionId(){return dimensionId;}public String getDimensionCode(){return dimensionCode;}public String getDimensionType(){return dimensionType;}public BigDecimal getActualValue(){return actualValue;}public String getManualBandId(){return manualBandId;}public String getMatchedLevelId(){return matchedLevelId;}public String getMatchedBandId(){return matchedBandId;}public BigDecimal getNumericScore(){return numericScore;}public BigDecimal getDimensionWeight(){return dimensionWeight;}public BigDecimal getWeightedContribution(){return weightedContribution;}public String getNarrative(){return narrative;}}
